englishMessages.push('Complete all required product details.','Restore','Previous','Next','Page {current} of {total}');
Object.assign(vi, { 'Complete all required product details.':'Vui l\u00f2ng \u0111i\u1ec1n \u0111\u1ea7y \u0111\u1ee7 c\u00e1c th\u00f4ng tin b\u1eaft bu\u1ed9c.','Restore':'Kh\u00f4i ph\u1ee5c','Previous':'Tr\u01b0\u1edbc','Next':'Ti\u1ebfp','Page {current} of {total}':'Trang {current}/{total}' });
const messages = { en: Object.freeze(Object.fromEntries(englishMessages.map(message => [message, message]))), vi: Object.freeze(vi) };
const messageKeys = new Map(Object.keys(messages.en).map(message => [message, message]));
const supportedLanguages = ['en', 'vi'];
const STORAGE_KEY = 'shophub-language';

export function getLanguage() {
  try { const stored = localStorage.getItem(STORAGE_KEY); return supportedLanguages.includes(stored) ? stored : 'en'; }
  catch { return 'en'; }
}
export function setLanguage(language) {
  const selected = supportedLanguages.includes(language) ? language : 'en';
  try { localStorage.setItem(STORAGE_KEY, selected); } catch { /* Language still applies for this page load. */ }
  return selected;
}
export function t(key, values = {}, language = getLanguage()) {
  let phrase = (messages[language] || messages.en)[key] || messages.en[key] || key;
  for (const [name, value] of Object.entries(values)) phrase = phrase.replaceAll(`{${name}}`, String(value));
  return phrase;
}

export function translateText(value, language = getLanguage()) {
  const leading = value.match(/^\s*/)?.[0] || '';
  const trailing = value.match(/\s*$/)?.[0] || '';
  const phrase = value.trim();
  if (!phrase) return value;
  if (language === 'vi' && phrase === 'MADE SLOWLY, LOVED FOR LONGER') return `${leading}CH\u1ebe T\u00c1C CH\u1eacM R\u00c3I, TR\u00c2N QU\u00dd D\u00c0I L\u00c2U${trailing}`;
  if (language === 'vi' && phrase === 'Made to last') return `${leading}B\u1ec1n \u0111\u1eb9p theo n\u0103m th\u00e1ng${trailing}`;
  if (language === 'vi' && phrase === 'Based on') return `${leading}D\u1ef1a tr\u00ean${trailing}`;
  const direct = messageKeys.has(phrase) ? t(messageKeys.get(phrase), {}, language) : null;
  if (direct !== null) return `${leading}${direct}${trailing}`;
  if (language === 'en') return value;
  let match = phrase.match(/^Search results for “(.+)”$/);
  if (match) return `${leading}Kết quả tìm kiếm cho “${match[1]}”${trailing}`;
  match = phrase.match(/^Results for “(.+)” — ShopHub$/);
  if (match) return `${leading}Kết quả cho “${match[1]}” — ShopHub${trailing}`;
  match = phrase.match(/^(.+) — ShopHub$/);
  if (match) return `${leading}${t(match[1], {}, language)} — ShopHub${trailing}`;
  match = phrase.match(/^View (.+)$/);
  if (match) return `${leading}Xem ${match[1]}${trailing}`;
  match = phrase.match(/^View product image (\d+)$/);
  if (match) return `${leading}Xem ảnh sản phẩm ${match[1]}${trailing}`;
  if (/^✓?\s*Verified shop$/.test(phrase)) return `${leading}✓ Cửa hàng uy tín${trailing}`;
  if (/^Verified independent shop\s*✓?$/.test(phrase)) return `${leading}Cửa hàng độc lập đã xác minh ✓${trailing}`;
  match = phrase.match(/^Save (.+)$/);
  if (match) return `${leading}Lưu ${match[1]}${trailing}`;
  match = phrase.match(/^Select (.+)$/);
  if (match) return `${leading}Chọn ${match[1]}${trailing}`;
  match = phrase.match(/^Shopping bag, (\d+) items?$/);
  if (match) return `${leading}Giỏ hàng, ${match[1]} sản phẩm${trailing}`;
  match = phrase.match(/^Your cart \((\d+)\)$/);
  if (match) return `${leading}Giỏ hàng (${match[1]})${trailing}`;
  match = phrase.match(/^(\d+) of (\d+) items selected$/);
  if (match) return `${leading}Đã chọn ${match[1]} trên ${match[2]} sản phẩm${trailing}`;
  match = phrase.match(/^Showing (\d+) of (\d+) finds$/);
  if (match) return `${leading}Đang hiển thị ${match[1]} / ${match[2]} sản phẩm${trailing}`;
  match = phrase.match(/^Add \$(\d+(?:\.\d{2})?) more from (.+) to unlock 10% off$/);
  if (match) return `${leading}Mua thêm $${match[1]} từ ${match[2]} để được giảm 10%${trailing}`;
  match = phrase.match(/^(\d+) selected · \$(\d+(?:\.\d{2})?) shop subtotal$/);
  if (match) return `${leading}${match[1]} đã chọn · Tạm tính cửa hàng $${match[2]}${trailing}`;
  if ((match = phrase.match(/^Sale savings \$(\d+(?:\.\d{2})?)\s+[^\w$]+\s+Shipping (on us|\$\d+(?:\.\d{2})?)$/))) return `${leading}Ti\u1ebft ki\u1ec7m $${match[1]} \u00b7 Ph\u00ed v\u1eadn chuy\u1ec3n ${match[2] === 'on us' ? 'mi\u1ec5n ph\u00ed' : match[2]}${trailing}`;
  match = phrase.match(/^Sale savings \$(\d+(?:\.\d{2})?)$/);
  if (match) return `${leading}Tiết kiệm $${match[1]}${trailing}`;
  match = phrase.match(/^Sale savings \$(\d+(?:\.\d{2})?) · Shipping (on us|\$\d+(?:\.\d{2})?)$/);
  if (match) return `${leading}Ti\u1ebft ki\u1ec7m $${match[1]} \u00b7 Ph\u00ed v\u1eadn chuy\u1ec3n ${match[2] === 'on us' ? 'mi\u1ec5n ph\u00ed' : match[2]}${trailing}`;
  match = phrase.match(/^Free shipping over \$(\d+(?:\.\d{2})?)$/);
  if (match) return `${leading}Miễn phí vận chuyển cho đơn từ $${match[1]}${trailing}`;
  match = phrase.match(/^Based on (\d+)$/);
  if (match) return `${leading}D\u1ef1a tr\u00ean ${match[1]}${trailing}`;
  match = phrase.match(/^Based on (\d+) reviews$/);
  if (match) return `${leading}D\u1ef1a tr\u00ean ${match[1]} \u0111\u00e1nh gi\u00e1${trailing}`;
  match = phrase.match(/^(.+) reviews$/);
  if (match) return `${leading}${match[1]} đánh giá${trailing}`;
  match = phrase.match(/^Checkout preview: (\d+) items? from (\d+) shops\. No order has been placed\.$/);
  if (match) return `${leading}Xem trước thanh toán: ${match[1]} sản phẩm từ ${match[2]} cửa hàng. Chưa có đơn hàng nào được đặt.${trailing}`;
  match = phrase.match(/^(.+) saved to your wishlist$/);
  if (match) return `${leading}Đã lưu ${match[1]} vào danh sách yêu thích${trailing}`;
  match = phrase.match(/^(.+) removed from your wishlist$/);
  if (match) return `${leading}Đã xóa ${match[1]} khỏi danh sách yêu thích${trailing}`;
  match = phrase.match(/^(.+) added to your bag$/);
  if (match) return `${leading}Đã thêm ${match[1]} vào giỏ hàng${trailing}`;
  match = phrase.match(/^(.+) removed from your cart$/);
  if (match) return `${leading}Đã xóa ${match[1]} khỏi giỏ hàng${trailing}`;
  match = phrase.match(/^(.+) saved for later$/);
  if (match) return `${leading}Đã lưu ${match[1]} để mua sau${trailing}`;
  match = phrase.match(/^(.+) moved back to your cart$/);
  if (match) return `${leading}Đã chuyển ${match[1]} lại vào giỏ hàng${trailing}`;
  match = phrase.match(/^(\d+) (?:item|items) removed from your cart$/);
  if (match) return `${leading}Đã xóa ${match[1]} sản phẩm khỏi giỏ hàng${trailing}`;
  match = phrase.match(/^(\d+) items? · (\d+) pieces?$/);
  if (match) return `${leading}${match[1]} sản phẩm · ${match[2]} món${trailing}`;
  match = phrase.match(/^ · Shipping (.+)$/);
  if (match) return `${leading} · Phí vận chuyển ${match[1]}${trailing}`;
  match = phrase.match(/^Decrease (.+) quantity$/);
  if (match) return `${leading}Giảm số lượng ${match[1]}${trailing}`;
  match = phrase.match(/^Increase (.+) quantity$/);
  if (match) return `${leading}Tăng số lượng ${match[1]}${trailing}`;
  match = phrase.match(/^(.+) color$/);
  if (match) return `${leading}Màu ${t(match[1], {}, language)}${trailing}`;
  match = phrase.match(/^(\d+) items?$/);
  if (match) return `${leading}${match[1]} sản phẩm${trailing}`;
  match = phrase.match(/^(.+) each$/);
  if (match) return `${leading}${match[1]} / sản phẩm${trailing}`;
  match = phrase.match(/^Based on (\d+) reviews$/);
  if (match) return `${leading}Dựa trên ${match[1]} đánh giá${trailing}`;
  match = phrase.match(/^Order today and it ships from (.+) in 1[–-]2 business days\.$/);
  if (match) return `${leading}\u0110\u1eb7t h\u00f4m nay, ${match[1]} s\u1ebd g\u1eedi h\u00e0ng trong 1\u20132 ng\u00e0y l\u00e0m vi\u1ec7c.${trailing}`;
  match = phrase.match(/^(\d+) star$/);
  if (match) return `${leading}${match[1]} sao${trailing}`;
  match = phrase.match(/^(\d+) independent shops?$/);
  if (match) return `${leading}${match[1]} cửa hàng độc lập${trailing}`;
  if (phrase === '. Each shop packs and ships its own order.') return `${leading}. Mỗi cửa hàng tự đóng gói và gửi đơn hàng của mình.${trailing}`;
  return value;
}

export function applyTranslations(root, language = getLanguage()) {
  if (!root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) node.nodeValue = translateText(node.nodeValue, language);
  const attributes = ['placeholder', 'aria-label', 'title'];
  root.querySelectorAll('*').forEach(element => {
    for (const attribute of attributes) {
      const value = element.getAttribute(attribute);
      if (value) element.setAttribute(attribute, translateText(value, language));
    }
  });
}

export function localizedPageTitle(pathname, search = '', language = getLanguage()) {
  if (language === 'en') return null;
  if (pathname === '/seller/products' || pathname === '/seller/products/') return `${t('Seller products', {}, language)} — ShopHub`;
  if (pathname === '/seller' || pathname === '/seller/' || pathname.startsWith('/seller/')) return `${t('Seller dashboard', {}, language)} — ShopHub`;
  if (pathname === '/reviews' || pathname === '/reviews/') return `${t('Reviews & ratings', {}, language)} — ShopHub`;
  if (pathname === '/account' || pathname === '/account/') return `${t('My account', {}, language)} — ShopHub`;
  if (pathname === '/wishlist' || pathname === '/wishlist/') return `${t('Wishlist', {}, language)} — ShopHub`;
  if (pathname === '/orders' || pathname === '/orders/') return `${t('My Orders', {}, language)} — ShopHub`;
  if (pathname.startsWith('/orders/')) return `${t('Order details', {}, language)} — ShopHub`;
  if (pathname === '/checkout' || pathname === '/checkout/') return `${t('Checkout', {}, language)} — ShopHub`;
  if (pathname === '/cart' || pathname === '/cart/') return 'Giỏ hàng — ShopHub';
  if (pathname.startsWith('/products/')) return null;
  if (pathname === '/products' || pathname === '/products/') {
    const params = new URLSearchParams(search);
    const query = params.get('q');
    if (query) return `Kết quả cho “${query}” — ShopHub`;
    return `${t(params.get('category') || (params.has('deal') ? 'Good deals' : 'All the good finds'), {}, language)} — ShopHub`;
  }
  return 'Tìm món đồ yêu thích tiếp theo — ShopHub';
}

export function localizedDescription(pathname, description, language = getLanguage()) {
  if (pathname === '/seller/products' || pathname === '/seller/products/') return t('Keep your listings, stock, and storefront details up to date.', {}, language);
  if (pathname === '/seller' || pathname === '/seller/' || pathname.startsWith('/seller/')) return t('Seller overview uses sample data for this prototype.', {}, language);
  if (pathname === '/reviews' || pathname === '/reviews/') return t('Review your purchases', {}, language);
  if (pathname.startsWith('/orders/')) return t('ShopHub order details for a sample order.', {}, language);
  if (language === 'en') return description;
  if (pathname === '/account' || pathname === '/account/') return t('Manage your details, delivery addresses, and saved finds.', {}, language);
  if (pathname === '/wishlist' || pathname === '/wishlist/') return t('Keep the pieces you love close.', {}, language);
  if (pathname === '/orders' || pathname === '/orders/' || pathname.startsWith('/orders/')) return t('Complete your ShopHub order history preview.', {}, language);
  if (pathname === '/checkout' || pathname === '/checkout/') return t('Complete your ShopHub checkout preview.', {}, language);
  if (pathname === '/cart' || pathname === '/cart/') return t('Review your finds from independent ShopHub sellers.', {}, language);
  if (pathname === '/products' || pathname === '/products/') return t("Shop the latest finds from ShopHub's independent makers and trusted shops.", {}, language);
  if (pathname.startsWith('/products/')) return t('Discover the story, details and maker behind this ShopHub find.', {}, language);
  return t('Find thoughtful goods from independent makers and trusted shops on ShopHub.', {}, language);
}

export const languageNames = Object.freeze({ en: 'English', vi: 'Tiếng Việt' });
